-- JHub protected build
local bkRNOro = "vESNGVIpZoMcsUHOn8d0imjYg21wr7+lBzbTtWaXx3R5ufK96DFC4hQLkPAq/Jey"
local oQ4XUpg = {
    zcU90ix = {k = {25,234,4,15,194,227,123,51,36,226,66,149,171,169,193,174}, d = ""},
    tvSiXS4 = {k = {70,228,169,132,213,109,90,203,133,58,138,140,135,173,183,243}, d = ""},
    sz1gL_7 = {k = {53,9,166,90,84,228,223,81,26,240,171,200,144,0,136,19}, d = ""},
    m_e3XAj = {k = {211,207,13,177,62,140,42,23,121,40,165,53,142,200,194,4}, d = ""},
}
local aRpbGZ7 = {
    "sz1gL_7", "m_e3XAj", "zcU90ix", "tvSiXS4"
}
local gqe8vkY = {
    [445348609] = true, [552857136] = true, [717744069] = true, [1266636585] = true, [1530873633] = true, [2184107246] = true, [2814290981] = true, [2853268356] = true, [3031180197] = true, [3613379573] = true, [3906248686] = true, [4246966418] = true
}
local l286Mta = "JHub/PB/jhub.key"

local function b64decode(s, alphabet)
    local rev = {}
    for i = 1, 64 do
        rev[string.byte(alphabet, i)] = i - 1
    end
    local EQ = string.byte("=")
    local len = #s
    while len > 0 and string.byte(s, len) == EQ do
        len -= 1
    end
    local outLen = (len * 6) // 8
    local buf = buffer.create(outLen)
    local acc, bits, pos = 0, 0, 0
    for i = 1, len do
        local v = rev[string.byte(s, i)]
        acc = acc * 64 + v
        bits += 6
        if bits >= 8 then
            bits -= 8
            local denom = 2 ^ bits
            local shifted = acc // denom
            buffer.writeu8(buf, pos, shifted % 256)
            pos += 1
            acc = acc % denom
        end
    end
    return buffer.tostring(buf)
end

local function xorReverse(s, key)
    local n = #s
    local src = buffer.create(n)
    buffer.writestring(src, 0, s)
    local kl = #key
    local out = buffer.create(n)
    for i = 0, n - 1 do
        local b = buffer.readu8(src, i)
        local revIdx = n - 1 - i
        local k = key[(revIdx % kl) + 1]
        buffer.writeu8(out, revIdx, bit32.bxor(b, k))
    end
    return buffer.tostring(out)
end

local function mulmod32(a, b)
    local a16 = a // 65536
    local a0 = a % 65536
    local hi = (a16 * b) % 4294967296
    local lo = (a0 * b) % 4294967296
    return (hi * 65536 + lo) % 4294967296
end

local function fnv1a32(s)
    local h = 2166136261
    for i = 1, #s do
        h = bit32.bxor(h, string.byte(s, i))
        h = mulmod32(h, 16777619)
    end
    return h
end

local function normKey(s)
    return string.lower((string.gsub(s or "", "%s+", "")))
end

local function reconstruct()
    local parts = table.create(#aRpbGZ7)
    for i, name in ipairs(aRpbGZ7) do
        local c = oQ4XUpg[name]
        local raw = b64decode(c.d, bkRNOro)
        parts[i] = xorReverse(raw, c.k)
    end
    return table.concat(parts)
end

local function run(...)
    local src = reconstruct()
    local chunkFn, err = loadstring(src, "JHub")
    if not chunkFn then
        warn("[JHub] protected payload failed to compile: " .. tostring(err))
        return
    end
    return chunkFn(...)
end

local function checkKey(raw)
    local norm = normKey(raw)
    if norm == "" then
        return false
    end
    return gqe8vkY[fnv1a32(norm)] == true
end

local function saveKey(norm)
    pcall(function()
        if not isfolder("JHub") then makefolder("JHub") end
        if not isfolder("JHub/PB") then makefolder("JHub/PB") end
        writefile(l286Mta, norm)
    end)
end

local function tryStoredKey()
    local ok, content = pcall(readfile, l286Mta)
    return ok and type(content) == "string" and checkKey(content)
end

local function promptKey(onSuccess)
    local okCore, CoreGui = pcall(function() return game:GetService("CoreGui") end)
    local gui = Instance.new("ScreenGui")
    gui.Name = "JHubKeyGate"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    local parented = false
    if okCore then
        parented = pcall(function() gui.Parent = CoreGui end)
    end
    if not parented then
        local lp = game:GetService("Players").LocalPlayer
        pcall(function() gui.Parent = lp:WaitForChild("PlayerGui", 10) end)
    end

    local frame = Instance.new("Frame")
    frame.Size = UDim2.new(0, 320, 0, 170)
    frame.Position = UDim2.new(0.5, -160, 0.5, -85)
    frame.BackgroundColor3 = Color3.fromRGB(24, 24, 28)
    frame.BorderSizePixel = 0
    frame.Parent = gui
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 10)
    corner.Parent = frame

    local title = Instance.new("TextLabel")
    title.Text = "JHub - Enter your key"
    title.Size = UDim2.new(1, -20, 0, 30)
    title.Position = UDim2.new(0, 10, 0, 12)
    title.BackgroundTransparency = 1
    title.TextColor3 = Color3.fromRGB(255, 255, 255)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 18
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = frame

    local box = Instance.new("TextBox")
    box.Size = UDim2.new(1, -20, 0, 36)
    box.Position = UDim2.new(0, 10, 0, 50)
    box.PlaceholderText = "Key"
    box.Text = ""
    box.ClearTextOnFocus = false
    box.BackgroundColor3 = Color3.fromRGB(40, 40, 46)
    box.TextColor3 = Color3.fromRGB(255, 255, 255)
    box.Font = Enum.Font.Gotham
    box.TextSize = 16
    box.Parent = frame
    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 6)
    boxCorner.Parent = box

    local errLabel = Instance.new("TextLabel")
    errLabel.Size = UDim2.new(1, -20, 0, 20)
    errLabel.Position = UDim2.new(0, 10, 0, 90)
    errLabel.BackgroundTransparency = 1
    errLabel.Text = ""
    errLabel.TextColor3 = Color3.fromRGB(255, 90, 90)
    errLabel.Font = Enum.Font.Gotham
    errLabel.TextSize = 13
    errLabel.TextXAlignment = Enum.TextXAlignment.Left
    errLabel.Parent = frame

    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, -20, 0, 34)
    btn.Position = UDim2.new(0, 10, 0, 118)
    btn.Text = "Unlock"
    btn.BackgroundColor3 = Color3.fromRGB(70, 120, 255)
    btn.TextColor3 = Color3.fromRGB(255, 255, 255)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 16
    btn.AutoButtonColor = true
    btn.Parent = frame
    local btnCorner = Instance.new("UICorner")
    btnCorner.CornerRadius = UDim.new(0, 6)
    btnCorner.Parent = btn

    local busy = false
    local function attempt()
        if busy then
            return
        end
        local text = box.Text
        if checkKey(text) then
            busy = true
            saveKey(normKey(text))
            pcall(function() gui:Destroy() end)
            onSuccess()
        else
            errLabel.Text = "Invalid key - try again"
        end
    end
    btn.MouseButton1Click:Connect(attempt)
    box.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            attempt()
        end
    end)
end

local function start(...)
    local n = select("#", ...)
    local args = table.pack(...)
    local function go()
        run(table.unpack(args, 1, n))
    end
    if tryStoredKey() then
        go()
    else
        promptKey(go)
    end
end

return start(...)
